const input = $input.first().json;
const data = input.body || input;

const allInputs = $input.all();
console.log('✅ Agent 3: Received', allInputs.length, 'item(s)');

if (allInputs.length !== 1) {
  console.error('⚠️ AGENT 3 ERROR: Expected 1 item, got', allInputs.length);
}

return [{
  json: {
    researchSummary: data.researchSummary,
    sources: data.sources || [],
    topic: data.topic,
    style: data.style,
    length: data.length,
    angle: data.angle,
    retryCount: 0
  }
}];

// Wait 2 seconds to give Data Tables time to execute in parallel
// This ensures they're available when Build Writing Prompt references them
await new Promise(resolve => setTimeout(resolve, 2000));

const parseInputData = $input.first().json;

console.log('✅ Agent 3: Waited for Data Tables, continuing to Build Writing Prompt');

return [{
  json: parseInputData
}];

// Get the original Parse Input data (not the Data Table data from previous node)
const data = $("Parse Input").first().json;

console.log('📝 Agent 3: Build Writing Prompt - Topic:', data.topic);

// Fetch Data Tables directly using node references (with error handling for empty tables)
let failures = [];
let metrics = [];
let retries = [];

try {
  failures = $("Get Validation Failures").all();
} catch (e) {
  console.log('⚠️ Agent 3: Validation Failures table empty or not executed');
}

try {
  metrics = $("Get Quality Metrics").all();
} catch (e) {
  console.log('⚠️ Agent 3: Quality Metrics table empty or not executed');
}

try {
  retries = $("Get Retry Patterns").all();
} catch (e) {
  console.log('⚠️ Agent 3: Retry Patterns table empty or not executed');
}

console.log('📊 Agent 3: Loaded', failures.length, 'failures,', metrics.length, 'metrics,', retries.length, 'retry patterns');

// Analyze learnings from Data Tables
const commonIssues = {};
failures.forEach(item => {
  const issue = item.json.issue_type || 'unknown';
  commonIssues[issue] = (commonIssues[issue] || 0) + 1;
});

const avgWordCount = metrics.length > 0 
  ? Math.round(metrics.reduce((sum, item) => sum + (item.json.word_count || 0), 0) / metrics.length)
  : 0;

const avgSectionCount = metrics.length > 0
  ? Math.round(metrics.reduce((sum, item) => sum + (item.json.section_count || 0), 0) / metrics.length)
  : 0;

const avgQualityScore = metrics.length > 0
  ? (metrics.reduce((sum, item) => sum + (item.json.quality_score || 0), 0) / metrics.length).toFixed(1)
  : 0;

let learnings = '';

if (Object.keys(commonIssues).length > 0) {
  const topIssues = Object.entries(commonIssues)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([issue, count]) => `- ${issue} (${count} occurrences)`);
  learnings += `\n\nCOMMON ISSUES TO AVOID:\n${topIssues.join('\n')}`;
}

if (metrics.length > 0) {
  learnings += `\n\nQUALITY BENCHMARKS (based on ${metrics.length} previous posts):\n`;
  learnings += `- Average word count: ${avgWordCount} words\n`;
  learnings += `- Average sections: ${avgSectionCount}\n`;
  learnings += `- Average quality score: ${avgQualityScore}/10`;
}

const sources = Array.isArray(data.sources) ? data.sources : [];
const sourcesText = sources.map((s, i) => `[${i+1}] ${s.title} - ${s.url}`).join('\n') || 'No sources';

const prompt = `You are a tech journalist writing an in-depth news analysis blog post. Write ABOUT the following topic from a third-person, objective perspective.

TOPIC: ${data.topic}
STYLE: ${data.style}
LENGTH: LONG-FORM (aim for 2500-5000 words - this is critical!)

RESEARCH:
${data.researchSummary}

SOURCES:
${sourcesText}${learnings}

CRITICAL INSTRUCTIONS:
- Write in THIRD PERSON (use "they", "the author", "the developer", NOT "I" or "we")
- Be a JOURNALIST reporting on the news, not the person in the story
- Analyze and explain the topic objectively
- If discussing someone work or opinion, refer to them by name or title
- Cite sources naturally in the text
- WRITE A COMPREHENSIVE DETAILED POST - aim for 2500-5000 words
- Expand on each section with multiple paragraphs, examples, and analysis
- Pay special attention to avoiding the common issues listed above
- Aim to meet or exceed the quality benchmarks shown above

Write a COMPLETE LONG-FORM blog post with:
- Title (MUST be first line) - make it newsworthy, not first-person
- Introduction (3-4 paragraphs) - set context and summarize what happened
- 6-10 main sections with headings - deeply analyze different aspects
- Each section should have 3-5 paragraphs with detailed analysis
- Include subsections where appropriate for complex topics
- Conclusion (3-4 paragraphs) - implications, future outlook, and takeaways

Output ONLY the markdown blog post, starting with title.`;

// CRITICAL: Only return ONE item to prevent duplication
return [{
  json: {
    model: 'gpt-oss:20b',
    prompt: prompt,
    stream: false,
    options: { temperature: 0.7 },
    sources: sources,
    topic: data.topic,
    style: data.style,
    length: data.length
  }
}];

const allInputs = $input.all();
const ollamaResponse = $input.first().json;
const prepData = $("Build Writing Prompt").first().json;

console.log('⚠️ Agent 3: Parse Blog Output received', allInputs.length, 'item(s)');

if (allInputs.length !== 1) {
  console.error('❌ DUPLICATION BUG: Expected 1 blog post, got', allInputs.length);
  console.error('This means the blog was generated multiple times!');
}

let blogContent = ollamaResponse.response || '';

const wordCount = blogContent.split(/\s+/).length;
console.log('✅ Agent 3: Generated', wordCount, 'words');

// CRITICAL: Only return the FIRST item to prevent duplication
return [{
  json: {
    blogContent: blogContent,
    topic: prepData.topic,
    style: prepData.style,
    length: prepData.length,
    sources: prepData.sources
  }
}];
